CREATE TABLE {{SCHEMA}}.jobs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, repo_id bigint NOT NULL REFERENCES {{SCHEMA}}.repos(id) ON DELETE CASCADE, type text NOT NULL CHECK (type IN ('sync','full_reindex')), status text NOT NULL CHECK (status IN ('pending','running','done','failed')), attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 3, run_after timestamptz NOT NULL DEFAULT now(), error text, heartbeat_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz);
CREATE UNIQUE INDEX jobs_pending_unique ON {{SCHEMA}}.jobs(repo_id,type) WHERE status='pending'; CREATE UNIQUE INDEX jobs_running_unique ON {{SCHEMA}}.jobs(repo_id) WHERE status='running'; CREATE INDEX jobs_claim_idx ON {{SCHEMA}}.jobs(status,run_after);
CREATE TABLE {{SCHEMA}}.index_runs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, repo_id bigint NOT NULL REFERENCES {{SCHEMA}}.repos(id) ON DELETE CASCADE, job_id bigint REFERENCES {{SCHEMA}}.jobs(id) ON DELETE SET NULL, from_sha text, to_sha text NOT NULL, status text NOT NULL CHECK (status IN ('running','succeeded','failed')), files_added integer NOT NULL DEFAULT 0, files_modified integer NOT NULL DEFAULT 0, files_deleted integer NOT NULL DEFAULT 0, files_unchanged integer NOT NULL DEFAULT 0, chunks_created integer NOT NULL DEFAULT 0, chunks_embedded integer NOT NULL DEFAULT 0, chunks_reused integer NOT NULL DEFAULT 0, chunks_deleted integer NOT NULL DEFAULT 0, embed_tokens bigint NOT NULL DEFAULT 0, config_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, error text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, duration_ms integer);
CREATE TABLE {{SCHEMA}}.query_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, repo_id bigint NOT NULL REFERENCES {{SCHEMA}}.repos(id) ON DELETE CASCADE, query text NOT NULL, rewritten_query text, intent text, indexed_sha text, retrieved_chunk_ids bigint[] NOT NULL DEFAULT '{}', reranked_chunk_ids bigint[] NOT NULL DEFAULT '{}', answer text, latencies_ms jsonb NOT NULL DEFAULT '{}'::jsonb, tokens_in integer, tokens_out integer, citation_check jsonb, pipeline_config jsonb NOT NULL DEFAULT '{}'::jsonb, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE {{SCHEMA}}.feedback (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, query_log_id bigint NOT NULL REFERENCES {{SCHEMA}}.query_logs(id) ON DELETE CASCADE, rating smallint NOT NULL CHECK (rating IN (-1,1)), comment text, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE {{SCHEMA}}.jobs ENABLE ROW LEVEL SECURITY; ALTER TABLE {{SCHEMA}}.index_runs ENABLE ROW LEVEL SECURITY; ALTER TABLE {{SCHEMA}}.query_logs ENABLE ROW LEVEL SECURITY; ALTER TABLE {{SCHEMA}}.feedback ENABLE ROW LEVEL SECURITY;
